/**
 * Vitest test to see if the Database can update a Playlist
 */
test('Test #6) Updating a Playlist in the Database', async () => {
    // GET PLAYLIST ID OF NEWLY CREATED PLAYLIST
    const playlists = await Playlist.find({ ownerEmail: "karen@elsh.com" });
    let playlistId;
    for (const playlist of playlists) {
        if (playlist.name === "Songsss") {
            playlistId = playlist._id;
            break;
        }
    }

    // NEXT TEST TO SEE IF IT WAS PROPERLY UPDATED
    // FILL IN A PLAYLIST WITH THE DATA YOU EXPECT THEM TO HAVE
    const expectedPlaylist = {
        name: "Songsss",
        ownerEmail: "karen@elsh.com",
        songs: [
            {
                "title": "Here Comes The Sun",
                "artist": "The Beatles",
                "year": 1969,
                "youTubeId": "xUNqsfFUwhY"
            },
        ]
    };
   
    const updatedData = { name: "Music Songs" };
    // UPDATE THE PLAYLIST
    await Playlist.findByIdAndUpdate(playlistId, updatedData, { new: true });

    // READ THE PLAYLIST, THIS WILL STORE THE DATA RETRUNED BY A READ PLAYLIST
    const actualPlaylist = await Playlist.findById(playlistId);

    // COMPARE THE VALUES OF THE EXPECTED PLAYLIST TO THE ACTUAL ONE
    expect(expectedPlaylist.name, actualPlaylist.name)
    expect(expectedPlaylist.ownerEmail, actualPlaylist.ownerEmail);
    expect(expectedPlaylist.songs, expectedPlaylist.songs);
});

/**
 * Vitest test to see if the Database Manager can delete a Playlist 
 */
test('Test #7) Deleting a Playlist in the Database', async () => {
    // MAKE A TEST PLAYLIST TO USE IN THE DATABASE
    const testPlaylist = {
        name: "Music Songs",
        ownerEmail: "karen@elsh.com",
        songs: [
            {
                "title": "Here Comes The Sun",
                "artist": "The Beatles",
                "year": 1969,
                "youTubeId": "xUNqsfFUwhY"
            },
        ]
    };

    // GET PLAYLIST ID
    const email = testPlaylist.ownerEmail;
    const playlists = await Playlist.find({ ownerEmail: email });
    let playlistId;
    for (const playlist of playlists) {
        if (playlist.name === testPlaylist.name) {
            playlistId = playlist._id;
            break;
        }
    }

    // DELETE THE PLAYLIST
    const expectedPlaylist = await Playlist.findByIdAndDelete(playlistId);

    // READ THE PLAYLIST, THIS WILL STORE THE DATA RETURNED BY A READ PLAYLIST
    const actualPlaylist = await Playlist.findById(playlistId);

    // COMPARE THE VALUES OF THE EXPECTED PLAYLIST TO THE ACTUAL ONE
    expect(expectedPlaylist, actualPlaylist);
})

